dict(id="INT-18", severity="note",
 location="paper.tex:120, :133, :135, :138",
 problem=r"""Wording a step beyond the source. :120 'over-correction removes biology' (source: over-correction may 'hinder biomedical discovery'). :133 'JS and KL divergences are not' (Thm 1 part 3 says statements 1-2 are false for them in general, as Example 1 shows). :135 omits 'compact' (Thm 2.1) and that Thm 2.2 gives zero gradient at almost every point of closed manifolds that do not align and lack full dimension. :138 Thm 3.1 shows that X + noise has a density; overlap of supports needs the positive Gaussian density of Cor. 3.1; scVI's posterior noise has a cell-specific scale, which the theorem does not cover directly.""",
 evidence=r"""Yu et al. 2024 abstract (over-correction may 'hinder biomedical discovery'); Arjovsky et al. 2017 Thm 1 (3), Example 1; Arjovsky and Bottou 2017 arXiv v1 Thms 2.1, 2.2, 3.1, Cor. 3.1 (statements read as text).""",
 fix="Adopt the replacement wording.",
 rep=[R(":120 (replace)", r"""\item Correction can fail both ways: uncorrected batch effects can mislead, and over-correction can hinder biomedical discovery \citep{yu2024assessing}."""),
      R(":133 (replace the end)", r"""... differentiable almost everywhere for locally Lipschitz ones (with a regularity assumption); for JS and Kullback--Leibler (KL) divergences these statements fail in general \citep[Thm.~1, part 3]{arjovsky2017wasserstein}."""),
      R(":135 (replace)", r"""\item For disjoint compact supports (Thm.~2.1), or supports on closed manifolds that do not perfectly align and do not have full dimension (Thm.~2.2), a perfect discriminator exists whose gradient is zero on the supports (everywhere in Thm.~2.1, at almost every point in Thm.~2.2) \citep[Thms.~2.1--2.2]{arjovsky2017towards}."""),
      R(":138 (replace)", r"""\item Continuous noise added to the discriminator input gives each distribution a density (Thm.~3.1); for Gaussian noise the density is positive everywhere, so the supports overlap \citep[Thm.~3.1, Cor.~3.1]{arjovsky2017towards}; scVI's posterior noise has a cell-specific scale, which the theorem does not cover directly.""")]),

